//go:build arm64

package gf256

// Region kernels generated by go-asmgen (gen/main.go) into gf256_arm64.s. They
// process the first n bytes, n a multiple of 16; tbl is the split nibble table.
func mulNEON(dst, src []byte, tbl *[32]byte, n int)
func mulAddNEON(dst, src []byte, tbl *[32]byte, n int)

func archTiers() []tier {
	return []tier{{"neon",
		func(dst, src []byte, c byte) int {
			n := len(src) &^ 15
			if n > 0 {
				mulNEON(dst, src, &nib[c], n)
			}
			return n
		},
		func(dst, src []byte, c byte) int {
			n := len(src) &^ 15
			if n > 0 {
				mulAddNEON(dst, src, &nib[c], n)
			}
			return n
		}}}
}
